/*:
 * @target MZ
 * @plugindesc Zetu's Point N Click Adventure
 * @author Zetu/DrJosephJorgen
 * @help NOTE GUIDE:
 * - Database/Items/note
 *
 *      - Start/End Notes:
 *          <zetu pnc>
 *          </zetu pnc>
 *      - Include Item in Point & Click Item Menu
 *          SHOW IN MENU {TYPE}
 *              TYPE = ICON (Uses the item db icon, 32x32 by default)
 *              TYPE = picture (Uses name of picture)
 *      - Common Event when inspecting item.
 *          SELF EVENT {commoneventid}
 */
/*
 * @param InventoryItemWidth
 * @text Item Width
 * @type number
 * @default 32
 *
 * @param InventoryItemHeight
 * @text Item Height
 * @type number
 * @default 32
 *
 * -------------------------------------------
 *
 * @command SetupSubscene
 * @text P&C: Setup Subscene
 * @desc Setup the Subscene for examining. With default window sizes, Max should be 792 x 376.
 *
 * @arg Width
 * @text Subscene Width
 * @type number
 * @default 792
 *
 * @arg Height
 * @text Subscene Height
 * @type number
 * @default 376
 *
 * @arg Items
 * @text Subscene Items
 * @type struct<SubsceneItem>[]
 *
 */
/*~struct~SubsceneItem:
 *
 * @param TileId
 * @text Tile Id
 * @type number
 * @desc Leave 0 to disable.
 * @default 0
 *
 * @param IconId
 * @text Icon Id
 * @type number
 * @desc Leave 0 to disable.
 * @default 0
 *
 * @param Picture
 * @text Picture
 * @type file
 * @desc Image of Item (if not tile/icon)
 * @dir pictures/pictures
 *
 * @param PictureFrames
 * @text Picture Frames
 * @type number
 * @desc The number of available frames on image
 *
 * @param PictureFrameIndex
 * @text Picture Frame Index Variable
 * @type variable
 * @desc If Picture Frames > 1, use this for Index
 * @default 0
 *
 * @param X
 * @text X Position
 * @type number
 * @desc Pixels from right
 * @default 0
 *
 * @param Y
 * @text Y Position
 * @type number
 * @desc Pixels from right
 * @default 0
 *
 * @param Zoom
 * @text Zoom Level
 * @type number
 * @decimals 2
 * @desc How far to zoom the item
 * @default 1.00
 *
 * @param Switch
 * @text Switch Required
 * @type switch
 * @desc If switch is needed to be ON/OFF
 *
 * @param SwitchState
 * @text Switch State
 * @type boolean
 * @on ON
 * @off OFF
 * @default true
 *
 * @param CommonEventId
 * @text Common Event
 * @type common_event
 *
 */

